// ignore_for_file: type=lint
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart' show defaultTargetPlatform, kIsWeb, TargetPlatform;

/// PLACEHOLDER — generated by hand, not by the `flutterfire configure` CLI.
///
/// These are syntactically valid but fake values. The app compiles and
/// builds fine with them (Firebase only validates credentials at runtime),
/// so this doesn't block the GitHub Actions APK build — but Google
/// Sign-In and the shared Nearby Rides feed won't actually work until you
/// swap this file for your own real one. See the README's "Google
/// Sign-In & Firebase setup" section for the exact steps: create a free
/// Firebase project, add an Android app to it with this project's
/// applicationId and the fixed debug-release SHA-1 printed by the CI
/// workflow, then run `flutterfire configure` (or copy values from
/// `google-services.json`) to replace the strings below.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('This app only ships for Android right now.');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions have not been configured for this platform.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'REPLACE_WITH_YOUR_FIREBASE_API_KEY',
    appId: '1:000000000000:android:0000000000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'replace-with-your-project-id',
    storageBucket: 'replace-with-your-project-id.appspot.com',
  );
}
